"""Markdown report for L1 results (docs/lanes/L1-safety-report-D1.md is generated by run_d1.py)."""
from __future__ import annotations

SECTIONS = [
    ("LS2", "Stair: open risers and gaps (life safety)"),
    ("LS1", "Stair: geometry, headroom, landings"),
    ("LS3", "Guards"),
    ("LS4", "Door next to the stair"),
    ("LS5", "Escape"),
    ("EG4", "Room heights"),
    ("EG5", "Room sizes"),
    ("EG6", "Doors"),
    ("EG7", "Openings and glazing ratio"),
    ("CL2", "Daylight factor per room"),
    ("EG9", "Window sills and falls"),
]

# Failures and warnings, cheapest fix first. Key = a substring of the result subject; value = (headline, fixes).
FIXES = [
    ("stair open-riser gap", "Open-riser stair: a 100 mm sphere passes and the treads do not overlap",
     ["Add riser boards between the treads (closed risers): removes both the gap and the overlap failure and meets the "
      "A+ target. Model it as 10-20 mm riser plates in concept/stairs.py `straight()`; no change to rise, going or the "
      "slab opening.",
      "Alternative if the floating look is kept: thicken the treads to >= 80 mm (gap 96.5 mm) AND lengthen each tread "
      "by 16 mm of overlap (tread depth 296 mm, run +0.26 m, which the 1.2 m top landing cannot absorb). Costlier."]),
    ("stair tread overlap", "Treads overlap 0 mm; ADK 1.9a asks 16 mm for open risers", ["Same fix as above (closed risers)."]),
    ("cinema (cinema) escape opening", "Cinema is a windowless inner room entered only through the lounge",
     ["Cheapest: reclassify the room as a store / plant / laundry (an inner room is allowed for utility use, ADB 2.11) "
      "and move the cinema to the deck end, where the end wall is a full-height window (the D3 arrangement: cinema "
      "under the deck, 2.65 m clear, window with blackout blind).",
      "Or: give the cinema an escape window or door. Its east wall is the plot boundary (fence), so there is no "
      "outside to open onto; only the deck-end position above has one.",
      "Or: accept an inner room with an interlinked smoke alarm and no sleeping use, as a recorded client "
      "decision (it is not an ADB-permitted use)."]),
    ("space under the flight", "Space under the lowest treads is open and under 2.0 m high",
     ["Enclose it as a cupboard or boxed-in understair store (closed risers make this natural), or fit a guard with "
      "low-level cane detection (ADK 1.8)."]),
    ("GF core door onto the stair top landing", "Core door sits 75 mm from the top step",
     ["Cheapest: hang the leaf to open OUTWARD into the shared core (or make it a sliding / pocket leaf), so nothing "
      "swings across the top landing. Confirm the swing in the Revit family (not modelled).",
      "Else: lengthen the landing so the door's near jamb is 0.4 m clear of the top step (about 0.33 m more landing "
      "length, which meets the column at x 3.977)."]),
    ("GF stair void edge", "No guard modelled round the GF opening (3.71 m of floor edge over the stair)",
     ["Add a 1.0-1.1 m glass or flat-bar guard along the opening edge on the corridor side, continuous with the stair "
      "glass; 100 mm sphere rule applies. Add it to revit_spec so the route-width check and the model agree."]),
    ("GF front terrace edge", "Terrace edge over the sunken patio has no guard in the model (3.0 m drop)",
     ["Add a 1.1 m guard along the terrace edge (5.08 m). Required by ADK K2(b)/3.2a for any drop over 0.6 m."]),
    ("patio edge beside the entrance steps", "Entrance-steps edge over the sunken patio has no guard (1.8 m drop)",
     ["Add a 1.1 m guard along the steps' edge on the patio side (ADK K2(b))."]),
    ("garden doors lead to a place of safety", "Basement escape through garden doors into closed yards is not proven",
     ["Draw the yard-to-street route (the car ramp and its gate, or a stair/gate in the street fence) and confirm "
      "the gate opens from inside without a key; then these rows can be marked pass."]),
    ("DF vs SLL minimum", "Basement rooms below the SLL minimum average daylight factor (recommendation)",
     ["Practical measures only (client: no light wells): glaze the lounge/kitchen faces floor-to-beam where the "
      "column grid allows, keep white finishes (already r12 default), keep guard rails clear glass; accept lower DF in "
      "the lounge and cinema and report it, because the client prefers shade. The kitchen has no opening of its own: "
      "it borrows light from dining/dirty kitchen; add a glazed pocket-door leaf or a window onto the east yard."]),
    ("glazing / floor area", "Habitable room glazing under 8 % of floor", ["See daylight row: only the kitchen and "
      "cinema have no own opening."]),
]


def _fmt(v):
    if v is None:
        return "-"
    return ("%.5g" % v) if isinstance(v, float) else str(v)


def _src(r, cards):
    out = []
    for sid in r.source_ids:
        c = cards.get(sid)
        out.append("%s (%s)" % (sid, c.locator.split(",")[0] if c else "?"))
    return "; ".join(out) or "-"


def _table(rows, cards, before=None):
    lines = ["| subject | gate | achieved | required | unit | before | status | source | note |",
             "|---|---|---|---|---|---|---|---|---|"]
    for r in rows:
        note = r.message.replace("|", "/")
        if len(note) > 170:
            note = note[:167] + "..."
        b = (before or {}).get((r.criterion, r.subject))
        bcell = "-" if b is None else (b["status"].upper() + ("" if b["gate"] == r.gate else " (%s)" % ("gate" if b["gate"] else "info")))
        if before is not None and b is None:
            bcell = "new"
        lines.append("| %s | %s | %s | %s | %s | %s | **%s** | %s | %s |" % (
            r.subject.replace("|", "/"), "gate" if r.gate else "info", _fmt(r.achieved), _fmt(r.required), r.unit, bcell, r.status.upper(), _src(r, cards), note))
    return "\n".join(lines)


def render(m, results, cards, before=None) -> str:
    gates = [r for r in results if r.gate]
    info = [r for r in results if not r.gate]
    n = lambda rows, st: sum(1 for r in rows if r.status == st)  # noqa: E731
    L = []
    L.append("# L1 safety and quality report: design D1 (international best practice)\n")
    L.append("Generated by `python -m archpipe.compliance.run_d1`; results in `out/checks/L1.json` (CheckResult v0.1). "
             "Lane L1, branch `lane/L1`.\n")
    L.append("## Scope\n")
    L.append("Client decision (2026-11): Egyptian compliance is not the bar. Gates are international best practice: UK "
             "Approved Documents K (stairs, guards, open risers), B (escape, inner rooms) and M (doors), Metric Handbook "
             "(ceiling height, NDSS room sizes, bathrooms), SLL Code (daylight factor), and the US IRC as quoted in "
             "Residential Interior Design (glazing 8 %, basement escape opening). Egyptian Executive Regulations rows "
             "(Law 119/2008, Andersen English translation, not checked against the Arabic Gazette) are reported as "
             "informative rows only (`gate=False`, cards `er119-*`, status `unverified`). Fire-code exemption (old EG1) "
             "and courtyard rules (old EG8) are dropped.\n")
    L.append("Threshold sources are cards in `knowledge/eg/best-practice-cards.json` (verbatim text, or the project's "
             "page-checked evidence card where marked `std`) and `knowledge/eg/er-119-2008.json`.\n")
    L.append("## Result in one line\n")
    L.append("Gates (%d rows): **%d pass, %d fail, %d warn, %d not evaluated**. Informative/target rows (%d): %d pass, "
             "%d fail, %d warn, %d not evaluated.\n" % (
                 len(gates), n(gates, "pass"), n(gates, "fail"), n(gates, "warn"), n(gates, "not_evaluated"),
                 len(info), n(info, "pass"), n(info, "fail"), n(info, "warn"), n(info, "not_evaluated")))
    waived = [r for r in info if "WAIVED" in r.message]
    if n(gates, "fail"):
        L.append("Grade effect under docs/quality/A-PLUS.md: %d failed life-safety gate(s) cap the grade at D.\n"
                 % n(gates, "fail"))
    else:
        L.append("Grade effect under docs/quality/A-PLUS.md: no gate fails; %d gate rows are not evaluated (a "
                 "gate that cannot be proved is not a pass). Recorded client waiver%s (G1 2026-11-21, still a "
                 "best-practice failure, kept visible as an info row): %s.\n" % (
                     n(gates, "not_evaluated"), "s" if len(waived) != 1 else "",
                     "; ".join(r.subject for r in waived) or "none"))
    if before is not None:
        L.append("## Before and after the G1 design fixes\n")
        bg = [v for v in before.values() if v["gate"]]
        L.append("Before (integ/aplus, `knowledge/eg/baseline-before-g1.json`): %d gate rows: %d pass, %d fail, %d warn, "
                 "%d not evaluated. After: %d gate rows: %d pass, %d fail, %d warn, %d not evaluated.\n" % (
                     len(bg), sum(v["status"] == "pass" for v in bg), sum(v["status"] == "fail" for v in bg),
                     sum(v["status"] == "warn" for v in bg), sum(v["status"] == "not_evaluated" for v in bg),
                     len(gates), n(gates, "pass"), n(gates, "fail"), n(gates, "warn"), n(gates, "not_evaluated")))
        changed = []
        for r in results:
            b = before.get((r.criterion, r.subject))
            if b is not None and (b["status"], b["gate"]) != (r.status, r.gate) and "[ER informative]" not in r.subject:
                changed.append((r, b))
        L.append("Rows whose status or gate flag changed:\n")
        L.append("| criterion | subject | before | after |")
        L.append("|---|---|---|---|")
        for r, b in changed:
            L.append("| %s | %s | %s (%s) | %s (%s) |" % (r.criterion, r.subject.replace("|", "/"), b["status"].upper(),
                                                         "gate" if b["gate"] else "info", r.status.upper(),
                                                         "gate" if r.gate else "info"))
        L.append("")
    L.append("## Failures and fixes, cheapest first\n")
    seen = set()
    k = 0
    for key, head, fixes in FIXES:
        rel = [r for r in results if key in r.subject and r.status in ("fail", "warn", "not_evaluated")
               and (r.gate or key in ("DF vs SLL minimum", "glazing / floor area"))]
        rel = [r for r in rel if "[ER informative]" not in r.subject]
        if not rel:
            continue
        k += 1
        L.append("### %d. %s\n" % (k, head))
        for r in rel:
            seen.add(id(r))
            L.append("- **%s %s** `%s`: achieved %s vs required %s %s. %s" % (
                r.criterion, r.status.upper(), r.subject, _fmt(r.achieved), _fmt(r.required), r.unit, r.message))
        L.append("")
        L.append("Fixes, cheapest first:")
        for i, f in enumerate(fixes, 1):
            L.append("%d. %s" % (i, f))
        L.append("")
    other = [r for r in results if r.gate and r.status != "pass" and id(r) not in seen]
    if other:
        L.append("### Other open gate rows\n")
        L.append(_table(other, cards, before))
        L.append("")
    L.append("## Every check, per room and element\n")
    L.append("`gate` rows are safety or quality gates; `info` rows are targets, recommendations or reports. Egyptian "
             "ER rows are listed separately below.\n")
    for crit, title in SECTIONS:
        rows = [r for r in results if r.criterion == crit and "[ER informative]" not in r.subject]
        if not rows:
            continue
        L.append("### %s %s\n" % (crit, title))
        L.append(_table(rows, cards, before))
        L.append("")
    L.append("## Informative and target rows (not gates)\n")
    L.append("Egyptian ER rows (`[ER informative]`), A+ targets and recommendations. Passing rows are counted, not "
             "listed.\n")
    bad = [r for r in info if r.status != "pass" and "[ER informative]" in r.subject]
    L.append(_table(bad, cards, before))
    L.append("")
    er = [r for r in info if "[ER informative]" in r.subject]
    L.append("Egyptian ER informative rows: %d, of which %d would fail. Failing ones: %s.\n" % (
        len(er), n(er, "fail"), "; ".join(sorted({r.subject.replace(" [ER informative]", "") for r in er if r.status == "fail"}))
        or "none"))
    L.append("## Margins on ASSUMED inputs\n")
    L.append("These pass by little, on assumed build-ups, so a small change flips them: stair headroom 2041 mm vs "
             "2000 (floor build-up 100 mm and slab 200 mm are ASSUMED); cinema floor share at 2.3 m clear 75.5 %% "
             "vs 75 (ramp soffit profile); parents' bedroom 11.52 m2 vs 11.5 (with the entry alcove); kids rooms "
             "11.81 and 11.75 vs 11.5; the stair guard and the ramp-edge guard sit exactly at their minimum heights "
             "(900 and 1100 mm).\n".replace("%%", "%"))
    L.append("## Data used and its limits\n")
    for s in m.sources:
        L.append("- " + s)
    L.append("- Room areas are estimated net areas (rect less 0.15 m each way); the Revit read-back "
             "(designs-r12, 2026-09-26) predates later D1 changes (client glass stair, pocket door, GF layout).")
    L.append("- Daylight factors are the project's validated Radiance run (`daylight/summary-r12.json`, basement rooms "
             "only; the GF rooms have no simulated DF, reported not evaluated). Clean glass, no furniture.")
    L.append("- Door and window widths are nominal; clear openings, openable areas and door swing are not modelled, so "
             "door and escape-window passes mean 'could qualify'.")
    L.append("- Beam depth (600) and slab soffit (slab 200 + build-up 100) are ASSUMED in the environment model.")
    L.append("- If lane L2 publishes `out/model/d1-elements.json`, replace `compliance/model.load_d1` reads; the "
             "checkers read only `DesignModel`.\n")
    return "\n".join(L) + "\n"
